function MazeUI:__init()
    --print("   ~~~~~~~ MazeUI:__init() ~~~~~~~")
    self.controller = nil
    self.coroutineRets = {}
end


function MazeUI:__delete()
    --print("   ~~~~~~~ MazeUI:__delete() ~~~~~~~")
end


function MazeUI:OnDestroy()
    self.controller = nil --删除lua层引用到的c#对象 否则不会产生c# gc回收到对象

    for i,co in pairs(self.coroutineRets) do 
        if not isNull(co) then
            cs_coroutine.stop(co)
            co = nil
        end
    end
    self.coroutineRets = nil


    self:Delete()
    --print("   ~~~~~~~ MazeUI:OnDestroy() ~~~~~~~")
end



function MazeUI:Awake()
    KTool.SetActive(self.controller.gameObject, true);
    --print("   ~~~~~~~ MazeUI:Awake() ~~~~~~~")

    printError( "本脚本已废弃, 需被 MazeMainUI 替代 ..." )
end



