---@param btn UnityEngine.UI.Button
---@return void
function MazeUI:PlayBtnPushAnimation( btn )
    assert( not isNull(btn) )
    assert( not isNull(self.btnAnimations[btn]) )
    assert( not isNull(self.btnPressedAnimationNames[btn] ) )
    self.btnAnimations[btn]:Play( self.btnPressedAnimationNames[btn] )
end


---@param btn     UnityEngine.UI.Button
---@param isShow  boolean -- show or hide
---@return void
function MazeUI:PlayBtnHideOrShowAnimation( btn, isShow )
    assert( not isNull(btn) )
    assert( not isNull(self.btnAnimations[btn]) )
    assert( not isNull(self.btnShowAnimationNames[btn] ) )
    assert( not isNull(self.btnHideAnimationNames[btn] ) )
    if isShow then
        self.btnAnimations[btn]:Play( self.btnShowAnimationNames[btn] )
    else 
        self.btnAnimations[btn]:Play( self.btnHideAnimationNames[btn] )
    end
end




---@return void
function MazeUI:WhenPushBtnTarget()
    local co_1 = cs_coroutine.start(self.OpenTaskNode, self)
    table.insert( self.coroutineRets, co_1 )
end

---@return void
function MazeUI:WhenPushBtnPutAway()
    local co_2 = cs_coroutine.start(self.CloseTaskNode, self)
    table.insert( self.coroutineRets, co_2 )
end



---@return void
function MazeUI:WhenPushBtnBack()
    MapDecryptionUtils.QuitMaze()  --- 退出迷宫
end


---@return System.Collections.IEnumerator
function MazeUI:OpenTaskNode()

    print("开启 taskNode");
    local tileWaitTime = 0.2 -- float
    local tileWaitTime2 = 0.07 -- float

    -- --- 隐藏 BtnTarget: (动画渐隐)
    self.BtnTargetAnimation:Play("SpringFestivalMazeMainDialog_BtnTarget_Pressed")
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime))
    self.BtnTarget.gameObject:SetActive(false)

    -- --- 显示 BtnPutAway: (直接显示不播动画)
    self.BtnPutAwayAnimation:Play("SpringFestivalMazeMainDialog_BtnPutAway_Return")
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime))
    self.BtnPutAway.gameObject:SetActive( true )

    self.targetInfoOrNodeAnimations = {} -- clear
   
    -- --- 依次展开 1~3 段条目 -- todo: 这个应该 根据需求来定 
    for i=1, 3 do
        local newgo = Object.Instantiate( self.TargetInfoOrNode.gameObject, self.InfoList.transform ) -- GameObject
        local animation  = KTool.GetComponent(newgo, typeof(Animation)) -- Animation
        animation:Play("SpringFestivalMazeMainDialog_TrainingTarget_Cell_Open")
        table.insert( self.targetInfoOrNodeAnimations, animation )
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime2))
    end
end

    

---@return System.Collections.IEnumerator
function MazeUI:CloseTaskNode()

    print("关闭 taskNode");
    local tileWaitTime = 0.2 -- float
    local tileWaitTime2 = 0.1 -- float

    -- --- 逐个释放 数个条目
    for i=#self.targetInfoOrNodeAnimations, 1, -1 do 
        
        local anim = self.targetInfoOrNodeAnimations[i] -- Animation
        table.remove( self.targetInfoOrNodeAnimations ) -- 默认删除尾元素
        anim:Play( "SpringFestivalMazeMainDialog_TrainingTarget_Cell_Closed" )
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime2))
        Object.Destroy( anim.gameObject )
    end

    -- --- 隐藏 BtnPutAway: 
    self.BtnPutAwayAnimation:Play("SpringFestivalMazeMainDialog_BtnPutAway_Pressed")
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime))
    self.BtnPutAway.gameObject:SetActive(false)
    
    -- --- 显示 BtnTarget: 
    self.BtnTargetAnimation:Play("SpringFestivalMazeMainDialog_BtnTarget_Return")
    cs_coroutine.yield_return(Yielders.GetWaitForSeconds(tileWaitTime))
    self.BtnTarget.gameObject:SetActive(true)
end



